package com.hsm.account.controller;
import com.hsm.account.entity.User;import com.hsm.account.service.AccountService;import com.hsm.common.ApiException;import com.hsm.security.SessionFilter;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.MediaType;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import javax.imageio.ImageIO;import java.io.IOException;import java.nio.file.*;import java.util.UUID;
@RestController @RequestMapping("/api/profile") public class ProfileImageController {private final AccountService service;private final Path root=Path.of(System.getProperty("user.dir"),"uploads");public ProfileImageController(AccountService s){service=s;} @PostMapping(value="/me/image",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) Object image(@RequestParam String kind,@RequestPart MultipartFile file,HttpServletRequest req)throws IOException{User u=(User)req.getAttribute(SessionFilter.USER);if(u==null)throw new ApiException(401,"UNAUTHENTICATED","Authentication is required.");if(!kind.equals("avatar")&&!kind.equals("cover"))throw new ApiException(400,"INVALID_IMAGE_KIND","Image kind must be avatar or cover.");if(file.isEmpty()||file.getSize()>5*1024*1024||(!"image/jpeg".equals(file.getContentType())&&!"image/png".equals(file.getContentType()))||ImageIO.read(file.getInputStream())==null)throw new ApiException(400,"INVALID_IMAGE","Only valid JPG or PNG images up to 5 MB are accepted.");Files.createDirectories(root);String name=u.getId()+"-"+kind+"-"+UUID.randomUUID()+("image/png".equals(file.getContentType())?".png":".jpg");Path target=root.resolve(name).normalize();if(!target.getParent().equals(root))throw new ApiException(400,"INVALID_IMAGE","Invalid upload path.");file.transferTo(target);return service.updateImage(u.getId(),kind,"/uploads/"+name);} }
